<script setup>import{showAlert}from'@/helpers/alert';import service from'@/services/display-point.service';import{computed,ref}from'vue';const props=defineProps({modelValue:Boolean,item:Object});const emit=defineEmits(['update:modelValue','deleted']);const busy=ref(false);const visible=computed({get:()=>props.modelValue,set:v=>emit('update:modelValue',v)});const remove=async()=>{try{busy.value=true;const r=await service.destroy(props.item.id);showAlert('success',r.message);emit('deleted');visible.value=false}catch(e){showAlert('error',e.response?.data)}finally{busy.value=false}};</script><template><Dialog v-model:visible="visible" modal :style="{width:'32rem'}" header="Excluir ponto de exibição"><p>Deseja excluir <strong>{{item?.name}}</strong>?</p><template #footer><Button label="Cancelar" text @click="visible=false"/><Button label="Excluir" severity="danger" :loading="busy" @click="remove"/></template></Dialog></template>
